const body = $json.body;
if (!body) return [];

if (body.sendByApi === true) return [];

if (body.typeWebhook === 'incomingMessageReceived' || body.typeWebhook === 'outgoingMessageReceived') {
  const senderData = body.senderData || {};
  const messageData = body.messageData || {};

  const chatId = senderData.chatId || body.chatId || '';
  if (chatId.includes('status@broadcast') || chatId.endsWith('@g.us')) return [];

  let text = '';
  if (messageData.typeMessage === 'textMessage') {
    text = (messageData.textMessageData && messageData.textMessageData.textMessage) || '';
  } else if (messageData.typeMessage === 'extendedTextMessage') {
    text = (messageData.extendedTextMessageData && messageData.extendedTextMessageData.text) || '';
  }

  if (!text) return [];

  const rawPhone = senderData.sender || chatId;
  const cleanPhone = rawPhone.replace('@c.us', '').replace('@s.whatsapp.net', '');

  return [{
    json: {
      sender_phone: cleanPhone,
      chat_id: chatId,
      patient_name: senderData.senderName || senderData.chatName || 'Sagar Patil',
      user_message: text,
      message_id: body.idMessage,
      timestamp: body.timestamp
    }
  }];
}

return [];

const userRaw = ($json.user_message || '').trim();
const userMsg = userRaw.toLowerCase();
const senderInfo = $json;
const chatId = senderInfo.chat_id || 'default';

