};

function parseSlotToIST(dateStr, timeStr) {
  const nowUtc = new Date();
  const istOffsetMs = 5.5 * 60 * 60 * 1000;
  const nowIst = new Date(nowUtc.getTime() + istOffsetMs);

  let targetYear = nowIst.getUTCFullYear();
  let targetMonth = nowIst.getUTCMonth();
  let targetDate = nowIst.getUTCDate() + 1; // default tomorrow

  const dLower = (dateStr || 'tomorrow').toLowerCase();
  if (dLower.includes('today') || dLower.includes('aaj')) {
    targetDate = nowIst.getUTCDate();
  } else if (dLower.includes('tomorrow') || dLower.includes('tommorrow') || dLower.includes('tommorow') || dLower.includes('tomorow') || dLower.includes('tomrw') || dLower.includes('tmrw') || dLower.includes('kal') || dLower.includes('kl')) {
    targetDate = nowIst.getUTCDate() + 1;
  } else {
    const days = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
    for (let i = 0; i < days.length; i++) {
      if (dLower.includes(days[i])) {
        const currentDay = nowIst.getUTCDay();
        let diff = (i - currentDay + 7) % 7;
        if (diff === 0) diff = 7;
        targetDate = nowIst.getUTCDate() + diff;
        break;
      }
    }
  }

  let hour = 11;
  let minute = 30;
  if (timeStr) {
    const t = timeStr.toLowerCase().trim();
    const isPm = t.includes('pm') || t.includes('bje') || t.includes('baje');
    const isAm = t.includes('am');
    const m = t.match(/(\d{1,2})(?::(\d{2}))?/);
    if (m) {
      let h = parseInt(m[1], 10);
      let min = m[2] ? parseInt(m[2], 10) : 0;
      if (isPm && h < 12) h += 12;
      if (isAm && h === 12) h = 0;
      if (!isPm && !isAm) {
        if (h >= 1 && h <= 7) h += 12;
      }
      hour = h;
      minute = min;
    }
  }

  const target = new Date(Date.UTC(targetYear, targetMonth, targetDate, hour, minute));
  const y = target.getUTCFullYear();
  const m = String(target.getUTCMonth() + 1).padStart(2, '0');
  const d = String(target.getUTCDate()).padStart(2, '0');
  const hh = String(target.getUTCHours()).padStart(2, '0');
  const mm = String(target.getUTCMinutes()).padStart(2, '0');

  const startISO = `${y}-${m}-${d}T${hh}:${mm}:00+05:30`;

  const endTarget = new Date(target.getTime() + 30 * 60 * 1000);
  const ey = endTarget.getUTCFullYear();
  const em = String(endTarget.getUTCMonth() + 1).padStart(2, '0');
  const ed = String(endTarget.getUTCDate()).padStart(2, '0');
  const ehh = String(endTarget.getUTCHours()).padStart(2, '0');
  const emm = String(endTarget.getUTCMinutes()).padStart(2, '0');

  const endISO = `${ey}-${em}-${ed}T${ehh}:${emm}:00+05:30`;
  return { startISO, endISO, hour: hh, minute: mm, dateStr: `${y}-${m}-${d}` };
}



