      "doc": "Dr. Nilesh Dhola",
      "address": "Gajera Circle, Katargam, Surat",
      "map": "https://www.google.com/maps/search/?api=1&query=Gajera+Circle+Katargam+Surat"
    }
  }
};
let replyText = "";
let isBooking = false;
let bookingData = null;

// Clean token split for whole-word matching
const words = userMsg.split(/[^a-zA-Z0-9]+/);

// Helper function for name extraction
function extractName(raw) {
  const m1 = raw.match(/([A-Za-z]+(?:\s+[A-Za-z]+)*)\s+(?:k|ke)\s+naam\s+se/i);
  if (m1) return m1[1].trim().replace(/^(?:.*\s+)?(?:ki|ko|ka|se|hai|for)\s+/i, '');

  const m2 = raw.match(/(?:patient|for|name(?:\s+is)?[:\s]+)\s*([A-Za-z]+(?:\s+[A-Za-z]+)?)/i);
  if (m2) return m2[1].trim();

  // If message is comma separated: "Sagar Patil, Tomorrow at 2:00 PM"
  if (raw.includes(',')) {
    const part = raw.split(',')[0].trim();
    if (part.split(' ').length <= 3 && !part.toLowerCase().includes('tomorrow') && !part.toLowerCase().includes('today')) {
      return part;
    }
  }

  // If user simply typed their name: "Neha Patil" or "Rahul"
  const clean = raw.trim();
  if (/^[A-Za-z\.\s]{2,30}$/.test(clean)) {
    const lower = clean.toLowerCase();
    const reserved = ['hi', 'hello', 'hey', 'start', 'help', 'menu', 'yes', 'confirm', 'vesu', 'pal', 'adajan', 'piplod', 'athwa', 'varachha', 'katargam', 'tomorrow', 'today'];
    if (!reserved.includes(lower) && !specMap[lower]) {
      return clean;
    }
  }

  return null;
}

// -------------------------------------------------------------
// CHECK COMMANDS: RESET / GREETING
// -------------------------------------------------------------
const greetings = ['hi', 'hello', 'hey', 'start', 'help', 'menu', 'hii', 'restart'];
if (greetings.includes(userMsg)) {
  session = {
    specialty: null,
    area: null,
    patientName: null,
    date: null,
    time: null
  };

  replyText = `Hello! Welcome to Surat Healthcare Assistant. 😊\nHow can we help you today?\n\n*STEP 1: Select Your Medical Specialist*\n1️⃣ *Cardiology* (Heart Care)\n2️⃣ *Dermatology* (Skin & Hair)\n3️⃣ *General Physician* (Fever, Cold, Checkup)\n4️⃣ *Orthopedics* (Bone & Joint Care)\n5️⃣ *Pediatrics* (Child Specialist)\n6️⃣ *Gynecology* (Women’s Health)\n7️⃣ *Dentistry* (Dental & Teeth)\n8️⃣ *ENT* (Ear, Nose & Throat)\n\n👉 *Reply with the number (1-8)* or specialty name!`;
}
// -------------------------------------------------------------
// CHECK CONFIRMATION (YES / CONFIRM)
// -------------------------------------------------------------
else if (userMsg === 'yes' || userMsg === 'confirm' || userMsg.includes('yes') || userMsg.includes('confirm')) {
  // If user included date or time in this message, update session
  if (userMsg.includes('tomorrow') || userMsg.includes('tommorrow') || userMsg.includes('tomorow') || userMsg.includes('tomrw') || userMsg.includes('tmrw') || words.includes('kl') || words.includes('kal')) {
    session.date = 'Tomorrow';
  } else if (userMsg.includes('today') || words.includes('aaj')) {
    session.date = 'Today';
  }
  const quickTime = userRaw.match(/(\d{1,2}(?::\d{2})?\s*(?:am|pm|bje|baje|o'clock)?)/i);
  if (quickTime && (userMsg.includes('pm') || userMsg.includes('am') || userMsg.includes('bje') || userMsg.includes('baje') || userMsg.includes(':'))) {
    session.time = quickTime[0].trim();
  }

  if (session.specialty && session.area && (session.patientName || session.time)) {
    isBooking = true;
    const finalName = session.patientName || senderInfo.patient_name || 'Patient';
    const finalSpec = session.specialty || 'General Physician';
    const finalArea = session.area || 'Surat';
    const specClinics = db[finalSpec] || db['General Physician'];
    const clinic = (specClinics && specClinics[finalArea]) || (db['General Physician'] && db['General Physician'][finalArea]) || {
      doc: 'Doctor',
      clinic: 'Surat Healthcare Clinic',
      address: `${finalArea}, Surat`,
      map: ''
    };

    const slot = parseSlotToIST(session.date, session.time);
    const startISO = slot.startISO;
    const endISO = slot.endISO;

    const finalWhen = (session.date ? session.date + ' ' : 'Tomorrow ') + (session.time ? 'at ' + session.time : 'at 11:30 AM');
    const bookingId = 'APT-' + Math.random().toString(36).substring(2, 8).toUpperCase();

    bookingData = {
      booking_id: bookingId,
      summary: `Doctor Appointment - ${finalSpec} (${finalName})`,
      description: `Patient: ${finalName}\nPhone: ${senderInfo.sender_phone}\nDoctor: ${clinic.doc}\nClinic: ${clinic.clinic}\nAddress: ${clinic.address}\nSpecialty: ${finalSpec}\nArea: ${finalArea}\nScheduled Time: ${finalWhen}\nBooked via Surat WhatsApp Healthcare Assistant`,
      start: startISO,
      end: endISO,
      location: `${finalArea}, Surat`,
      patient_name: finalName,
      doctor: clinic.doc,
      clinic: clinic.clinic,
      address: clinic.address,
      map: clinic.map || '',
      area: finalArea,
      specialty: finalSpec,
      phone: senderInfo.sender_phone,
      scheduled_time: finalWhen,
      date_str: session.date || 'Tomorrow',
      time_str: session.time || '11:30 AM'
    };

    replyText = `🎉 *APPOINTMENT CONFIRMED!*\n\n• *Appointment ID:* ${bookingId}\n• *Patient Name:* ${finalName}\n• *Specialty:* ${finalSpec}\n• *Area:* ${finalArea}\n• *Doctor:* ${clinic.doc}\n• *Clinic:* ${clinic.clinic}\n• *Address:* ${clinic.address}\n• *Date & Time:* ${finalWhen} (IST)\n• *Status:* Scheduled on Doctor Google Calendar\n• *Phone:* ${senderInfo.sender_phone}\n\nThank you for choosing Surat Healthcare Assistant. Please arrive 10 minutes prior to your slot! 🩺`;

    // Reset session after successful booking
    session = { specialty: null, area: null, patientName: null, date: null, time: null };
  } else {
    replyText = `To confirm your appointment, we still need your details! Please reply *Hi* to restart or provide your preferred specialty and area.`;
  }
}
// -------------------------------------------------------------
// ANALYZE & EXTRACT DETAILS ACCORDING TO RULE SET
// -------------------------------------------------------------
else {
  // 1. Extract Area (Only match 1-7 if specialty is already chosen!)
  let detectedArea = null;
  if (/^[1-7]$/.test(userMsg)) {
    if (session.specialty && !session.area) {
      detectedArea = areaNumMap[userMsg];
    }
  }
  if (!detectedArea) {
    for (const [k, v] of Object.entries(areaMap)) {
      if (words.includes(k)) {
        detectedArea = v;
        break;
      }
    }
  }
  if (detectedArea) session.area = detectedArea;

  // 2. Extract Specialty
  let detectedSpec = null;
  if (/^[1-8]$/.test(userMsg)) {
    if (!session.specialty) {
      detectedSpec = specMap[userMsg];
    }
  } else {
    for (const [kw, spec] of Object.entries(specMap)) {
      if (!/^\d$/.test(kw) && words.includes(kw)) {
        detectedSpec = spec;
        break;
      }
    }
  }
  if (detectedSpec) session.specialty = detectedSpec;

  // 3. Extract Name
  const detectedName = extractName(userRaw);
  if (detectedName) session.patientName = detectedName;

  // 4. Extract Date
  if (userMsg.includes('tomorrow') || userMsg.includes('tommorrow') || userMsg.includes('tomorow') || userMsg.includes('tomrw') || userMsg.includes('tmrw') || words.includes('kl') || words.includes('kal')) {
    session.date = 'Tomorrow';
  } else if (userMsg.includes('today') || words.includes('aaj')) {
    session.date = 'Today';
  } else {
    const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
    for (const d of days) {
      if (userMsg.includes(d)) {
        session.date = d.charAt(0).toUpperCase() + d.slice(1);
        break;
      }
    }
  }

  // 5. Extract Time
  const timeMatch = userRaw.match(/(\d{1,2}(?::\d{2})?\s*(?:am|pm|bje|baje|o'clock)?)/i);
  if (timeMatch && (userMsg.includes('pm') || userMsg.includes('am') || userMsg.includes('bje') || userMsg.includes('baje') || userMsg.includes(':'))) {
    session.time = timeMatch[0].trim();
  }

  // -----------------------------------------------------------
  // DECISION TREE (Check what is left: Specialty -> Area -> Name/Time)
  // -----------------------------------------------------------

  // A. Missing Specialty?
  if (!session.specialty) {
    const ack = (session.patientName || session.time) ? `Got your request${session.patientName ? ` for *${session.patientName}*` : ''}${session.time ? ` at *${session.date || ''} ${session.time}*` : ''}.\n\n` : '';
    replyText = `${ack}Please select the *Medical Specialist* you need:\n\n1️⃣ *Cardiology* (Heart Care)\n2️⃣ *Dermatology* (Skin & Hair)\n3️⃣ *General Physician* (Fever, Cold, Checkup)\n4️⃣ *Orthopedics* (Bone & Joint Care)\n5️⃣ *Pediatrics* (Child Specialist)\n6️⃣ *Gynecology* (Women’s Health)\n7️⃣ *Dentistry* (Dental & Teeth)\n8️⃣ *ENT* (Ear, Nose & Throat)\n\n👉 *Reply with the number (1-8)* or specialty name!`;
  }
  // B. Missing Area?
  else if (!session.area) {
    replyText = `Great! You selected *${session.specialty}*.\n\n*STEP 2: Select Your Preferred Area in Surat*\n📍 1. *Vesu*\n📍 2. *Piplod*\n📍 3. *Adajan*\n📍 4. *Pal*\n📍 5. *Athwa*\n📍 6. *Varachha*\n📍 7. *Katargam*\n\n👉 *Reply with the area name (e.g. Vesu, Pal) or number (1-7)*!`;
  }
  // C. Has Specialty & Area, check if Name or Date/Time is missing!
  else if (!session.patientName || !session.date || !session.time) {
    const spec = session.specialty;
    const specClinics = db[spec] || db['General Physician'];
    const clinic = specClinics[session.area] || db['General Physician'][session.area];

    // Subcase C1: Both Name AND Time/Date are missing -> show full clinic card
    if (!session.patientName && (!session.date || !session.time)) {
      replyText = `*STEP 3: Available Doctor & Clinic in ${session.area}*\n\n👨‍⚕️ *Doctor:* ${clinic.doc}\n🏥 *Clinic:* ${clinic.clinic}\n📍 *Address:* ${clinic.address}\n🗺️ *Maps:* ${clinic.map}\n\n🕒 *Working Hours:* Mon–Sat, 10:00 AM – 6:00 PM (Lunch: 1:00 PM – 2:00 PM)\n\n💡 *Suggested Next Slots:*\n• Tomorrow at 10:30 AM\n• Tomorrow at 11:30 AM\n• Tomorrow at 3:00 PM\n• Tomorrow at 4:30 PM\n\n👉 *Please reply with your *Patient Full Name* and *Preferred Date & Time**\n*(Example: "Sagar Patil, Tomorrow at 11:30 AM")*`;
    }
    // Subcase C2: User ALREADY provided Date/Time, but Patient Name is still missing!
    else if (!session.patientName) {
      const when = (session.date ? session.date + ' ' : '') + session.time;
      replyText = `Got your requested slot (*${when}*) for *${clinic.doc}* at *${clinic.clinic}*! 🕒\n\n👉 *Please reply with the Patient's Full Name* to finalize your appointment!\n*(e.g., "Sagar Patil" or "Rahul Patel")*`;
    }
    // Subcase C3: User ALREADY provided Patient Name, but Date/Time is still missing!
    else {
      replyText = `Got it, appointment for *${session.patientName}* with *${clinic.doc}*! 👤\n\n💡 *Suggested Next Slots:*\n• Tomorrow at 10:30 AM\n• Tomorrow at 11:30 AM\n• Tomorrow at 3:00 PM\n• Tomorrow at 4:30 PM\n\n👉 *Please reply with your Preferred Date & Time* (e.g., "Tomorrow at 4:00 PM")!`;
    }
  }
  // D. Everything present! Show Booking Summary Card (Step 4)
  else {
    const spec = session.specialty;
    const specClinics = db[spec] || db['General Physician'];
    const clinic = specClinics[session.area] || db['General Physician'][session.area];
    const when = `${session.date} at ${session.time}`;

