function extractName(raw) {
  const m1 = raw.match(/([A-Za-z]+(?:\s+[A-Za-z]+)*)\s+(?:k|ke)\s+naam\s+se/i);
  if (m1) return m1[1].trim().replace(/^(?:.*\s+)?(?:ki|ko|ka|se|hai|for)\s+/i, '');

  const m2 = raw.match(/(?:patient|for|name(?:\s+is)?[:\s]+)\s*([A-Za-z]+(?:\s+[A-Za-z]+)?)/i);
  if (m2) return m2[1].trim();

  // If message is comma separated: "Sagar Patil, Tomorrow at 2:00 PM"
  if (raw.includes(',')) {
    const part = raw.split(',')[0].trim();
    if (part.split(' ').length <= 3 && !part.toLowerCase().includes('tomorrow') && !part.toLowerCase().includes('today')) {
      return part;
    }
  }

  // If user simply typed their name: "Neha Patil" or "Rahul"
  const clean = raw.trim();
  if (/^[A-Za-z\.\s]{2,30}$/.test(clean)) {
    const lower = clean.toLowerCase();
    const reserved = ['hi', 'hello', 'hey', 'start', 'help', 'menu', 'yes', 'confirm', 'vesu', 'pal', 'adajan', 'piplod', 'athwa', 'varachha', 'katargam', 'tomorrow', 'today'];
    if (!reserved.includes(lower) && !specMap[lower]) {
      return clean;
    }
  }

  return null;
}

