    // Subcase C1: Both Name AND Time/Date are missing -> show full clinic card
    if (!session.patientName && (!session.date || !session.time)) {
      replyText = `*STEP 3: Available Doctor & Clinic in ${session.area}*\n\n👨‍⚕️ *Doctor:* ${clinic.doc}\n🏥 *Clinic:* ${clinic.clinic}\n📍 *Address:* ${clinic.address}\n🗺️ *Maps:* ${clinic.map}\n\n🕒 *Working Hours:* Mon–Sat, 10:00 AM – 6:00 PM (Lunch: 1:00 PM – 2:00 PM)\n\n💡 *Suggested Next Slots:*\n• Tomorrow at 10:30 AM\n• Tomorrow at 11:30 AM\n• Tomorrow at 3:00 PM\n• Tomorrow at 4:30 PM\n\n👉 *Please reply with your *Patient Full Name* and *Preferred Date & Time**\n*(Example: "Sagar Patil, Tomorrow at 11:30 AM")*`;
    }
    // Subcase C2: User ALREADY provided Date/Time, but Patient Name is still missing!
    else if (!session.patientName) {
      const when = (session.date ? session.date + ' ' : '') + session.time;
      replyText = `Got your requested slot (*${when}*) for *${clinic.doc}* at *${clinic.clinic}*! 🕒\n\n👉 *Please reply with the Patient's Full Name* to finalize your appointment!\n*(e.g., "Sagar Patil" or "Rahul Patel")*`;
    }
    // Subcase C3: User ALREADY provided Patient Name, but Date/Time is still missing!
    else {
      replyText = `Got it, appointment for *${session.patientName}* with *${clinic.doc}*! 👤\n\n💡 *Suggested Next Slots:*\n• Tomorrow at 10:30 AM\n• Tomorrow at 11:30 AM\n• Tomorrow at 3:00 PM\n• Tomorrow at 4:30 PM\n\n👉 *Please reply with your Preferred Date & Time* (e.g., "Tomorrow at 4:00 PM")!`;
    }
  }
  // D. Everything present! Show Booking Summary Card (Step 4)
  else {
    const spec = session.specialty;
    const specClinics = db[spec] || db['General Physician'];
    const clinic = specClinics[session.area] || db['General Physician'][session.area];
    const when = `${session.date} at ${session.time}`;

    replyText = `*STEP 4: Review Your Booking Summary* 📋\n\n• *Patient Name:* ${session.patientName}\n• *Specialty:* ${session.specialty}\n• *Doctor:* ${clinic.doc}\n• *Clinic:* ${clinic.clinic}\n• *Address:* ${clinic.address}\n• *Scheduled Time:* ${when}\n• *Phone:* ${senderInfo.sender_phone}\n\n👉 *Reply YES or CONFIRM to finalize and schedule in Google Calendar!*`;
  }
}

// Save session
staticData.userSessions[chatId] = session;

return [{
  json: {
    has_booking: isBooking,
    booking_data: bookingData,
    chat_id: senderInfo.chat_id,
    patient_name: session.patientName || senderInfo.patient_name,
    sender_phone: senderInfo.sender_phone,
    reply_message: replyText
  }
}];

parameters.jsonBody:
={
  "chatId": "{{ $('Parse AI Booking Action').item.json.chat_id }}",
  "message": {{ JSON.stringify($('Parse AI Booking Action').item.json.reply_message) }}
}
